('1', '1', '3', 'https://picsum.photos/seed/novel1/300/400', '2026-08-05 10:00:00', '少年林夜自小城走出，觉醒星辰血脉，踏上问鼎苍穹的修行之路。', '星辰之巅', '-1', '3', '4.7', '连载', '4852', '49424'),
