('6', '6', '3', 'https://picsum.photos/seed/novel6/300/400', '2026-07-16 10:00:00', '一场意外让两个陌生人相遇，从此琴瑟和鸣，岁月静好。', '锦瑟年华', '-1', '3', '4.5', '连载', '2288', '32656'),
('7', '1', '6', 'https://picsum.photos/seed/novel7/300/400', '2026-07-12 10:00:00', '一柄锈剑，一个落魄少年，走出了一条震撼九州的剑道。', '剑道独尊', '-1', '3', '4.0', '连载', '5326', '53646'),
('8', '2', '3', 'https://picsum.photos/seed/novel8/300/400', '2026-07-08 10:00:00', '重回一九九八，他凭借记忆中的大势，一步步缔造商业帝国。', '重生之商界传奇', '-1', '1', '3.8', '连载', '3445', '44648'),
