消息传开的时候，整个客栈都安静了一瞬。随后是窃窃私语，再然后，便是一阵压抑的骚动。

这一战，无人知晓会以怎样的方式落幕。但他握紧手中的剑，目光如炬，没有半分退缩的意思。

有些真相，掩埋得越久，揭开时便越惊心动魄。他不知道自己即将触碰的，是怎样的过往。

