有些真相，掩埋得越久，揭开时便越惊心动魄。他不知道自己即将触碰的，是怎样的过往。

夜色如墨，风从旷野尽头席卷而来。他立在城头，望着远处若隐若现的灯火，心中翻涌着难以言说的情绪。

